    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;

    vector<int> mp(n + 1, 0);
    for (int i = 0, value; i < n; ++i) {
        cin >> value;
        if (value >= 0 && value <= n)
            ++mp[value];
    }

    int x = 0;
    while (x <= n && mp[x] > 0)
        ++x;

    if (x > k)
        cout << "1\n";
    else if (x == k)
        cout << "0\n";
    else
        cout << k - x << '\n';

    return 0;
}

